import { expect, expectStatus, test, type APIRequestContext } from "../../fixtures";

const KINDS = ["w9", "insurance_certificate", "contract"] as const;

function uniqueVendorName(): string {
  return `LIF-02 Vendor ${Date.now()}-${Math.random().toString(36).slice(2, 8)}`;
}

async function waitForExtracted(api: APIRequestContext, documentId: string) {
  for (let attempt = 0; attempt < 30; attempt++) {
    const response = await api.get(`/api/documents/${documentId}`);
    const doc = await expectStatus<{ status: string }>(response, 200);
    if (doc.status === "extracted") return;
    if (doc.status === "failed") throw new Error(`document ${documentId} failed extraction`);
    await new Promise((resolve) => setTimeout(resolve, 500));
  }
  throw new Error(`document ${documentId} never reached extracted`);
}

test(
  "rejecting one document sends the whole vendor back",
  { tag: "@LIF-02" },
  async ({ apiAs }) => {
    // Arrange: a member creates a vendor, uploads three documents, and submits it.
    const member = await apiAs("member");
    const reviewer = await apiAs("reviewer");

    const created = await expectStatus<{ id: string }>(
      await member.post("/api/vendors", {
        data: {
          name: uniqueVendorName(),
          category: "services",
          contact_email: `lif02-${Date.now()}@example.test`,
        },
      }),
      201,
    );
    const vendorId = created.id;

    const documentIds: Record<string, string> = {};
    for (const kind of KINDS) {
      const doc = await expectStatus<{ id: string }>(
        await member.post(`/api/vendors/${vendorId}/documents`, {
          multipart: {
            kind,
            file: {
              name: `${kind}.pdf`,
              mimeType: "application/pdf",
              buffer: Buffer.from(`%PDF-1.4 sample ${kind}`),
            },
          },
        }),
        201,
      );
      documentIds[kind] = doc.id;
    }

    for (const id of Object.values(documentIds)) {
      await waitForExtracted(member, id);
    }

    await expectStatus(await member.post(`/api/vendors/${vendorId}/submit`), 200);

    // Locate the contract extraction and confirm the precondition: pending review.
    const contractExtraction = await expectStatus<{ id: string; status: string }>(
      await member.get(`/api/documents/${documentIds.contract}/extraction`),
      200,
    );
    expect(contractExtraction.status).toBe("pending_review");

    const pendingBefore = await expectStatus<{ status: string }>(
      await member.get(`/api/vendors/${vendorId}`),
      200,
    );
    expect(pendingBefore.status).toBe("in_review");

    // Act: reviewer rejects the contract extraction with a note.
    const decision = await expectStatus<{ id: string; status: string; review_note: string | null }>(
      await reviewer.post(`/api/extractions/${contractExtraction.id}/decision`, {
        data: { decision: "reject", note: "Wrong counterparty" },
      }),
      200,
    );

    // Assert: the extraction is rejected and the vendor is sent back.
    expect(decision.status).toBe("rejected");
    expect(decision.review_note).toBe("Wrong counterparty");

    const vendor = await expectStatus<{ status: string }>(
      await member.get(`/api/vendors/${vendorId}`),
      200,
    );
    expect(vendor.status).toBe("rejected");

    // Assert: audit events are recorded in order, extraction.rejected before vendor.rejected.
    const audit = await expectStatus<{ items: { action: string }[] }>(
      await member.get(`/api/vendors/${vendorId}/audit`),
      200,
    );
    const actions = audit.items.map((event) => event.action);
    const extractionIdx = actions.indexOf("extraction.rejected");
    const vendorIdx = actions.indexOf("vendor.rejected");

    expect(extractionIdx).toBeGreaterThanOrEqual(0);
    expect(vendorIdx).toBeGreaterThanOrEqual(0);
    expect(extractionIdx).toBeLessThan(vendorIdx);
  },
);
